def parse_json(text: str) -> object:
    n = len(text)
    i = 0

    def error():
        raise ValueError("Invalid JSON")

    def skip_ws():
        nonlocal i
        while i < n and text[i] in (' ', '\t', '\n', '\r'):
            i += 1

    def parse_string():
        nonlocal i
        i += 1
        parts = []
        while True:
            if i >= n:
                error()
            ch = text[i]
            if ch == '"':
                i += 1
                return ''.join(parts)
            if ord(ch) < 0x20:
                error()
            if ch == '\\':
                i += 1
                if i >= n:
                    error()
                esc = text[i]
                if esc == '"':
                    parts.append('"'); i += 1
                elif esc == '\\':
                    parts.append('\\'); i += 1
                elif esc == '/':
                    parts.append('/'); i += 1
                elif esc == 'b':
                    parts.append('\b'); i += 1
                elif esc == 'f':
                    parts.append('\f'); i += 1
                elif esc == 'n':
                    parts.append('\n'); i += 1
                elif esc == 'r':
                    parts.append('\r'); i += 1
                elif esc == 't':
                    parts.append('\t'); i += 1
                elif esc == 'u':
                    i += 1
                    if i + 4 > n:
                        error()
                    hs = text[i:i+4]
                    for c in hs:
                        if c not in '0123456789abcdefABCDEF':
                            error()
                    cp = int(hs, 16)
                    i += 4
                    if 0xD800 <= cp <= 0xDBFF:
                        if i + 6 > n:
                            error()
                        if text[i] != '\\' or text[i+1] != 'u':
                            error()
                        i += 2
                        hs2 = text[i:i+4]
                        for c in hs2:
                            if c not in '0123456789abcdefABCDEF':
                                error()
                        cp2 = int(hs2, 16)
                        i += 4
                        if not (0xDC00 <= cp2 <= 0xDFFF):
                            error()
                        parts.append(chr(0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)))
                    elif 0xDC00 <= cp <= 0xDFFF:
                        error()
                    else:
                        parts.append(chr(cp))
                else:
                    error()
            else:
                parts.append(ch)
                i += 1

    def parse_number():
        nonlocal i
        start = i
        if text[i] == '-':
            i += 1
        if i >= n:
            error()
        if text[i] == '0':
            i += 1
            if i < n and '0' <= text[i] <= '9':
                error()
        elif '1' <= text[i] <= '9':
            i += 1
            while i < n and '0' <= text[i] <= '9':
                i += 1
        else:
            error()
        has_frac = has_exp = False
        if i < n and text[i] == '.':
            has_frac = True
            i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                error()
            while i < n and '0' <= text[i] <= '9':
                i += 1
        if i < n and text[i] in ('e', 'E'):
            has_exp = True
            i += 1
            if i < n and text[i] in ('+', '-'):
                i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                error()
            while i < n and '0' <= text[i] <= '9':
                i += 1
        if has_frac or has_exp:
            return float(text[start:i])
        return int(text[start:i])

    _CONT = object()
    stack = []

    def parse_value_or_start():
        nonlocal i
        ch = text[i]
        if ch == '{':
            i += 1
            stack.append(['obj', {}, 'start', None])
            return _CONT
        if ch == '[':
            i += 1
            stack.append(['arr', [], 'start', None])
            return _CONT
        if ch == '"':
            return parse_string()
        if ch == 't':
            if text[i:i+4] != 'true' or (i + 4 < n and text[i+4].isalnum()):
                error()
            i += 4
            return True
        if ch == 'f':
            if text[i:i+5] != 'false' or (i + 5 < n and text[i+5].isalnum()):
                error()
            i += 5
            return False
        if ch == 'n':
            if text[i:i+4] != 'null' or (i + 4 < n and text[i+4].isalnum()):
                error()
            i += 4
            return None
        if ch == '-' or '0' <= ch <= '9':
            return parse_number()
        error()

    def _complete():
        frame = stack.pop()
        completed = frame[1]
        if not stack:
            return completed
        pf = stack[-1]
        if pf[0] == 'arr':
            pf[1].append(completed)
            pf[2] = 'post'
        else:
            pf[1][pf[3]] = completed
            pf[2] = 'post'
        return None

    skip_ws()
    if i >= n:
        error()

    while True:
        if not stack:
            val = parse_value_or_start()
            if val is _CONT:
                continue
            skip_ws()
            if i < n:
                error()
            return val

        frame = stack[-1]
        kind = frame[0]
        state = frame[2]

        if state == 'start':
            skip_ws()
            if i >= n:
                error()
            ch = text[i]
            if kind == 'arr' and ch == ']':
                i += 1
                r = _complete()
                if r is not None:
                    skip_ws()
                    if i < n: error()
                    return r
                continue
            if kind == 'obj' and ch == '}':
                i += 1
                r = _complete()
                if r is not None:
                    skip_ws()
                    if i < n: error()
                    return r
                continue
            if kind == 'obj':
                if ch != '"':
                    error()
                key = parse_string()
                if key in frame[1]:
                    error()
                frame[3] = key
                frame[2] = 'colon'
                continue
            val = parse_value_or_start()
            if val is _CONT:
                continue
            frame[1].append(val)
            frame[2] = 'post'

        elif state == 'after_comma':
            skip_ws()
            if i >= n:
                error()
            ch = text[i]
            if kind == 'obj':
                if ch != '"':
                    error()
                key = parse_string()
                if key in frame[1]:
                    error()
                frame[3] = key
                frame[2] = 'colon'
                continue
            val = parse_value_or_start()
            if val is _CONT:
                continue
            frame[1].append(val)
